import React, { useEffect, useMemo, useState } from "react";
import { createRoot } from "react-dom/client";
import "../styles/page.css";
import { DEFAULT_PROVIDER_MODEL } from "../shared/models";
import { clearHistory, deleteHistoryItem, getStorage } from "../shared/storage";
import type { AssistantSettings, HistoryItem } from "../shared/types";

function PopupApp() {
  const [settings, setSettings] = useState<AssistantSettings>();
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const accent = useMemo(() => (settings?.defaultSelectionAction === "creative" ? "#9334e6" : "#1a73e8"), [settings?.defaultSelectionAction]);

  async function refresh() {
    const data = await getStorage();
    setSettings(data.settings);
    setHistory(data.history.slice(0, 6));
  }

  useEffect(() => {
    void refresh();
  }, []);

  return (
    <main className="w-[360px] bg-[#f8fafd] text-[#202124]" style={{ fontFamily: "Google Sans, Roboto, Arial, sans-serif" }}>
      <section className="px-5 pb-4 pt-5">
        <div className="flex items-center gap-3">
          <div className="grid h-11 w-11 place-items-center rounded-[22px] text-lg text-white shadow-sm" style={{ background: accent }}>
            ✦
          </div>
          <div className="min-w-0 flex-1">
            <h1 className="truncate text-base font-medium tracking-normal">AI Context Assistant</h1>
            <p className="truncate text-xs text-[#5f6368]">{settings?.provider.provider ?? "gemini"} · {settings?.provider.model ?? DEFAULT_PROVIDER_MODEL.gemini}</p>
          </div>
        </div>
      </section>

      <section className="border-y border-[#dadce0] bg-white px-5 py-3">
        <div className="grid grid-cols-2 gap-2">
          <button className="rounded-full px-4 py-2 text-sm font-medium text-white" style={{ background: accent }} onClick={() => chrome.tabs.create({ url: chrome.runtime.getURL("settings.html#custom-actions") })}>
            Custom buttons
          </button>
          <button className="rounded-full border px-4 py-2 text-sm font-medium" style={{ borderColor: "#dadce0", color: accent }} onClick={() => chrome.tabs.create({ url: chrome.runtime.getURL("settings.html") })}>
            Settings
          </button>
        </div>
      </section>

      <section className="px-5 py-4">
        <div className="mb-2 flex items-center justify-between">
          <h2 className="text-xs font-medium uppercase tracking-wide text-[#5f6368]">Recent</h2>
          <button
            className="rounded-full px-3 py-1 text-xs font-medium"
            style={{ color: "#b3261e" }}
            onClick={async () => {
              await clearHistory();
              setHistory([]);
            }}
          >
            Clear
          </button>
        </div>
        <div className="space-y-2">
          {history.length === 0 && <p className="rounded-2xl border border-dashed border-[#dadce0] bg-white p-3 text-sm text-[#5f6368]">No recent history yet.</p>}
          {history.map((item) => (
            <div key={item.id} className="rounded-2xl border border-[#dadce0] bg-white p-3">
              <div className="mb-1 flex items-center justify-between gap-2">
                <div className="text-xs font-medium" style={{ color: accent }}>{item.actionName}</div>
                <button
                  className="grid h-7 w-7 place-items-center rounded-full text-base"
                  style={{ color: "#b3261e" }}
                  title="Delete"
                  onClick={async () => {
                    await deleteHistoryItem(item.id);
                    setHistory((current) => current.filter((entry) => entry.id !== item.id));
                  }}
                >
                  ×
                </button>
              </div>
              <p className="line-clamp-2 text-sm leading-5 text-[#202124]">{item.result}</p>
            </div>
          ))}
        </div>
      </section>
    </main>
  );
}

createRoot(document.getElementById("root")!).render(<PopupApp />);
